      "content": "{\n  \"name\": \"@ethanyoq/dsh-ai-novel-writer\",\n  \"version\": \"0.1.0\",\n  \"description\": \"A local-first novel project plugin for DeepSeek Harness\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/EthanYoQ/AI-Novel-Writer.git\",\n    \"directory\": \"plugins/dsh-ai-novel-writer\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/EthanYoQ/AI-Novel-Writer/issues\"\n  },\n  \"homepage\": \"https://github.com/EthanYoQ/AI-Novel-Writer/tree/master/plugins/dsh-ai-novel-writer#readme\",\n  \"publishConfig\": {\n    \"access\": \"public\"\n  },\n  \"type\": \"module\",\n  \"packageManager\": \"pnpm@11.11.0\",\n  \"main\": \"lib/index.js\",\n  \"types\": \"lib/types/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./lib/types/index.d.ts\",\n      \"default\": \"./lib/index.js\"\n    },\n    \"./agent\": {\n      \"types\": \"./lib/types/agent.d.ts\",\n      \"default\": \"./lib/agent.js\"\n    },\n    \"./agent-v2\": {\n      \"types\": \"./lib/types/agent-v2.d.ts\",\n      \"default\": \"./lib/agent-v2.js\"\n    },\n    \"./client\": {\n      \"types\": \"./lib/types/client/index.d.ts\",\n      \"default\": \"./lib/client.js\"\n    },\n    \"./cordis.patch.yml\": \"./cordis.patch.yml\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"lib/index.js\",\n    \"lib/agent.js\",\n    \"lib/agent-v2.js\",\n    \"lib/client.js\",\n    \"lib/types/**/*.d.ts\",\n    \"cordis.patch.yml\",\n    \"presets/**\",\n    \"README.md\",\n    \"LICENSE\",\n    \"THIRD_PARTY_NOTICES.md\"\n  ],\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-runtime\",\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-ui-layout\",\n        \"@deepseek-ai/dsh-client-ui-settings-plugins\",\n        \"@deepseek-ai/dsh-client-ui-sidebar\"\n      ],\n      \"platform\": \"web\"\n    }\n  },\n  \"engines\": {\n    \"node\": \"^22.19 || >=24\"\n  },\n  \"scripts\": {\n    \"build\": \"tsc -p tsconfig.build.json && tsdown && node scripts/link-self.mjs && node scripts/verify-built.mjs\",\n    \"bundle\": \"tsdown\",\n    \"test\": \"pnpm run build && vitest run\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"qualify\": \"node scripts/qualify-release.mjs\"\n  },\n  \"dependencies\": {\n    \"@deepseek-ai/dsh-atomic-write\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-home-paths\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/schemastery\": \"3.18.1\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.1\",\n    \"@deepseek-ai/dsh-agent\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-agent-instructions\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-agent-presets\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-brand\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-connection\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-runtime\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-layout\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-sidebar\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-llm\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-persona\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-scope\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-session\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-tools\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-workspace\": \"0.1.0-rc.6\",\n    \"react\": \"^18.2.0\",\n    \"react-dom\": \"^18.2.0\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/cordis\": \"4.0.1\",\n    \"@deepseek-ai/cordis-plugin-include\": \"1.0.6\",\n    \"@deepseek-ai/cordis-plugin-loader\": \"1.0.2\",\n    \"@deepseek-ai/dsh-agent\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-agent-instructions\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-agent-loop\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-agent-presets\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-api-gateway\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-attachment\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-brand\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-connection\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-locale\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-runtime\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-schema-form\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-layout\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-settings-plugins\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-settings\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-sidebar\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-slots\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-client-ui-theme\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-code-runtime\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-cordis-host-runner\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-fs\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-home-paths\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-host-plugin-inventory\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-host-webserver\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-invariants\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-llm\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-message-feedback\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-persona\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-sandbox\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-scope\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-session\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-settings\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-storage\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-storage-domain\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-system-prompt\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-timeout\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-tools\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-typert-registry\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-user-approval\": \"0.1.0-rc.6\",\n    \"@deepseek-ai/dsh-workspace\": \"0.1.0-rc.6\",\n    \"@types/js-yaml\": \"^4.0.9\",\n    \"@types/node\": \"^25.0.0\",\n    \"@types/react\": \"~18.3.1\",\n    \"@types/react-dom\": \"~18.3.1\",\n    \"js-yaml\": \"4.3.2\",\n    \"jsdom\": \"29.1.1\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\",\n    \"tsdown\": \"^0.22.2\",\n    \"typescript\": \"^6.0.2\",\n    \"vitest\": \"^4.1.4\"\n  },\n  \"license\": \"MIT\"\n}\n"
    },
