      "content": "{\n  \"name\": \"ai-novel-writer\",\n  \"version\": \"1.4.0\",\n  \"description\": \"AI Novel Writer - a local-first production workspace for long-form fiction\",\n  \"author\": \"AI Novel Writer Maintainers\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"packageManager\": \"pnpm@11.11.0\",\n  \"engines\": {\n    \"node\": \">=22.14.0\"\n  },\n  \"main\": \"dist-electron/main.js\",\n  \"scripts\": {\n    \"postinstall\": \"node node_modules/electron/install.js\",\n    \"dev\": \"vite\",\n    \"clean:build\": \"node scripts/clean-build-output.mjs\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"check:i18n\": \"node scripts/check-i18n-coverage.mjs\",\n    \"test\": \"vitest run\",\n    \"test:browser\": \"vitest run --config vitest.browser.config.ts\",\n    \"verify:drive\": \"node scripts/redesign/drive.mjs\",\n    \"build\": \"tsc && vite build\",\n    \"build:win\": \"pnpm run release:win:verify\",\n    \"build:win:artifacts\": \"node scripts/require-release-gate.mjs && tsc && vite build && electron-builder --win --x64 --publish never\",\n    \"release:win:verify\": \"node scripts/release-win-verify.mjs\",\n    \"build:win-dir\": \"pnpm run clean:build && pnpm run typecheck && vite build && electron-builder --win dir --x64 && pnpm run verify:win-package\",\n    \"build:mac:artifacts\": \"pnpm run build:mac:arm64:artifacts\",\n    \"build:mac:arm64:artifacts\": \"pnpm run clean:build && pnpm run typecheck && clang -fobjc-arc -framework Foundation electron/security/darwin-safe-file-system.m -o electron/security/darwin-safe-file-system && chmod +x electron/security/darwin-safe-file-system && vite build && node scripts/build-release-vector-smoke-runner.mjs && electron-builder --mac --arm64 --publish never\",\n    \"build:mac:x64:artifacts\": \"pnpm run clean:build && pnpm run typecheck && clang -fobjc-arc -framework Foundation electron/security/darwin-safe-file-system.m -o electron/security/darwin-safe-file-system && chmod +x electron/security/darwin-safe-file-system && vite build && node scripts/build-release-vector-smoke-runner.mjs && electron-builder --mac --x64 --publish never\",\n    \"verify:win-package\": \"node scripts/verify-win-package.mjs\",\n    \"verify:win-update-artifacts\": \"node scripts/verify-win-update-artifacts.mjs\",\n    \"verify:github-update-release\": \"node scripts/verify-github-update-release.mjs\",\n    \"smoke:win-app\": \"powershell -NoProfile -ExecutionPolicy Bypass -File scripts/smoke-win-app.ps1\",\n    \"smoke:win-installer\": \"powershell -NoProfile -ExecutionPolicy Bypass -File scripts/smoke-win-installer.ps1\",\n    \"smoke:win-v025-upgrade\": \"powershell -NoProfile -ExecutionPolicy Bypass -File scripts/smoke-win-v025-upgrade.ps1\",\n    \"smoke:mac-dmg\": \"bash scripts/smoke-macos-dmg.sh\",\n    \"lint\": \"eslint . --ext ts,tsx --report-unused-disable-directives --max-warnings 0 && node scripts/check-color-literals.mjs\",\n    \"preview\": \"vite preview\",\n    \"storybook\": \"storybook dev -p 6006\",\n    \"build-storybook\": \"storybook build\"\n  },\n  \"dependencies\": {\n    \"@codemirror/lang-markdown\": \"^6.5.0\",\n    \"@codemirror/language\": \"^6.12.3\",\n    \"@codemirror/language-data\": \"^6.5.2\",\n    \"@codemirror/search\": \"^6.7.1\",\n    \"@codemirror/state\": \"^6.6.0\",\n    \"@codemirror/view\": \"^6.41.0\",\n    \"@lancedb/lancedb\": \"0.22.3\",\n    \"@lezer/highlight\": \"^1.2.3\",\n    \"@radix-ui/react-dialog\": \"^1.1.15\",\n    \"@radix-ui/react-label\": \"^2.1.8\",\n    \"@radix-ui/react-select\": \"^2.2.6\",\n    \"@radix-ui/react-separator\": \"^1.1.8\",\n    \"@radix-ui/react-slot\": \"^1.2.4\",\n    \"@radix-ui/react-tabs\": \"^1.1.13\",\n    \"@radix-ui/react-tooltip\": \"^1.2.8\",\n    \"@uiw/react-codemirror\": \"^4.25.9\",\n    \"apache-arrow\": \"^18.1.0\",\n    \"better-sqlite3\": \"^13.0.3\",\n    \"class-variance-authority\": \"^0.7.1\",\n    \"clsx\": \"^2.1.1\",\n    \"diff-match-patch\": \"^1.0.5\",\n    \"electron-updater\": \"6.8.9\",\n    \"flatbuffers\": \"^25.9.23\",\n    \"lucide-react\": \"^1.8.0\",\n    \"react\": \"^19.2.5\",\n    \"react-dom\": \"^19.2.5\",\n    \"react-markdown\": \"^10.1.0\",\n    \"react-resizable-panels\": \"^4.9.0\",\n    \"reflect-metadata\": \"^0.2.2\",\n    \"rehype-raw\": \"^7.0.0\",\n    \"remark-gfm\": \"^4.0.1\",\n    \"tailwind-merge\": \"^3.5.0\",\n    \"tailwindcss-animate\": \"^1.0.7\",\n    \"yauzl\": \"^2.10.0\",\n    \"zustand\": \"^5.0.0\"\n  },\n  \"devDependencies\": {\n    \"@chromatic-com/storybook\": \"^5.1.2\",\n    \"@storybook/addon-a11y\": \"^10.6.2\",\n    \"@storybook/addon-docs\": \"^10.6.2\",\n    \"@storybook/addon-onboarding\": \"^10.6.2\",\n    \"@storybook/addon-vitest\": \"^10.6.2\",\n    \"@storybook/react-vite\": \"^10.6.2\",\n    \"@tailwindcss/vite\": \"^4.2.2\",\n    \"@types/better-sqlite3\": \"^7.6.13\",\n    \"@types/diff-match-patch\": \"^1.0.36\",\n    \"@types/react\": \"^19.2.14\",\n    \"@types/react-dom\": \"^19.2.3\",\n    \"@types/yauzl\": \"^2.10.3\",\n    \"@typescript-eslint/eslint-plugin\": \"^8.58.1\",\n    \"@typescript-eslint/parser\": \"^8.58.1\",\n    \"@vitejs/plugin-react\": \"^6.0.1\",\n    \"@vitest/browser-playwright\": \"^4.1.10\",\n    \"@vitest/coverage-v8\": \"^4.1.10\",\n    \"electron\": \"^44.9.3\",\n    \"electron-builder\": \"^26.15.0\",\n    \"esbuild\": \"^0.28.1\",\n    \"eslint\": \"^8.57.1\",\n    \"eslint-plugin-react-hooks\": \"^7.0.1\",\n    \"eslint-plugin-react-refresh\": \"^0.4.19\",\n    \"eslint-plugin-storybook\": \"^10.6.2\",\n    \"fast-check\": \"^4.10.1\",\n    \"playwright\": \"^1.59.1\",\n    \"postcss\": \"^8.5.18\",\n    \"storybook\": \"^10.6.2\",\n    \"tailwindcss\": \"^4.2.2\",\n    \"typescript\": \"^6.0.2\",\n    \"vite\": \"^8.2.4\",\n    \"vite-plugin-electron\": \"^0.29.1\",\n    \"vite-plugin-electron-renderer\": \"^0.14.5\",\n    \"vitest\": \"^4.1.10\"\n  },\n  \"optionalDependencies\": {\n    \"@lancedb/lancedb-darwin-arm64\": \"0.22.3\",\n    \"@lancedb/lancedb-darwin-x64\": \"0.22.3\",\n    \"@lancedb/lancedb-win32-x64-msvc\": \"0.22.3\"\n  }\n}\n"
